<svg {viewBox} class={extra} role="img" aria-label="lytebuy lantern">
	<defs>
		<radialGradient id={flameId} cx="50%" cy="65%" r="60%">
			<stop offset="0%" stop-color="#ffffff" />
			<stop offset="30%" stop-color="#ffe27a" />
			<stop offset="60%" stop-color="#ffb02e" />
			<stop offset="100%" stop-color="#ff4500" />
		</radialGradient>
		<radialGradient id={glowId} cx="50%" cy="50%" r="50%">
			<stop offset="0%" stop-color="#ffcf6b" stop-opacity="0.85" />
			<stop offset="100%" stop-color="#ffcf6b" stop-opacity="0" />
		</radialGradient>
		<filter id={softId} x="-60%" y="-60%" width="220%" height="220%">
			<feGaussianBlur stdDeviation="0.4" />
		</filter>
	</defs>
	<g class="lb-light">
		<ellipse cx="96.6" cy="145.7" rx="6.5" ry="7.5" fill="url(#{glowId})" class="lb-glow" />
		<g class="lb-flame" filter="url(#{softId})">
			<path
				fill="url(#{flameId})"
				d="M 96.6 149.9 C 93.8 147.7, 94.7 144.0, 96.6 141.3 C 98.5 144.0, 99.4 147.7, 96.6 149.9 Z"
			/>
			<path
				fill="#fff6d8"
				opacity="0.95"
				d="M 96.6 149.3 C 95.2 147.9, 95.7 145.5, 96.6 143.9 C 97.5 145.5, 98.0 147.9, 96.6 149.3 Z"
			/>
		</g>
	</g>
	<path fill={ink} d={LANTERN_D} />
</svg>

<style>
	.lb-flame {
		animation: lb-flicker 1.6s ease-in-out infinite alternate;
		transform-box: fill-box;
		transform-origin: center bottom;
	}
	.lb-glow {
		animation: lb-pulse 1.6s ease-in-out infinite alternate;
		transform-box: fill-box;
		transform-origin: center center;
	}
	@keyframes lb-flicker {
		0% {
			transform: rotate(-2deg) scaleY(0.94) scaleX(1.02);
		}
		35% {
			transform: rotate(1.5deg) scaleY(1.05) scaleX(0.98);
		}
		70% {
			transform: rotate(-1deg) scaleY(0.98);
		}
		100% {
			transform: rotate(2deg) scaleY(1.06) scaleX(0.97);
		}
	}
	@keyframes lb-pulse {
		0% {
			opacity: 0.75;
			transform: scale(0.94);
		}
		100% {
			opacity: 1;
			transform: scale(1.06);
		}
	}
	@media (prefers-reduced-motion: reduce) {
		.lb-flame,
		.lb-glow {
			animation: none;
		}
	}
</style>
